func startNativeInputReader(reader io.Reader) <-chan struct{} {
	closed := make(chan struct{})
	go func() {
		defer close(closed)
		buffer := make([]byte, 64*1024)
		for {
			n, err := reader.Read(buffer)
			if n > 0 {
				nativeInputMu.Lock()
				_, _ = nativeInputBuffer.Write(buffer[:n])
				nativeInputMu.Unlock()
			}
			if err != nil {
				return
			}
		}
	}()
	return closed
}

