func decodeDeckAssets(text string) (map[string]DeckAsset, string, error) {
	match := keynopeAssetsRE.FindStringSubmatch(text)
	if match == nil {
		return nil, text, nil
	}
	compressed, err := base64.StdEncoding.DecodeString(match[1])
	if err != nil {
		return nil, text, fmt.Errorf("decode embedded assets: %w", err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return nil, text, fmt.Errorf("open embedded assets: %w", err)
	}
	data, err := io.ReadAll(io.LimitReader(reader, 100<<20))
	closeErr := reader.Close()
	if err != nil || closeErr != nil {
		return nil, text, fmt.Errorf("read embedded assets: %w", errors.Join(err, closeErr))
	}
	assets := map[string]DeckAsset{}
	if err := json.Unmarshal(data, &assets); err != nil {
		return nil, text, fmt.Errorf("parse embedded assets: %w", err)
	}
	return assets, keynopeAssetsRE.ReplaceAllString(text, ""), nil
}

func encodeDeckAssets(assets map[string]DeckAsset) (string, error) {
	if len(assets) == 0 {
		return "", nil
	}
	data, err := json.Marshal(assets)
	if err != nil {
		return "", err
	}
	var compressed bytes.Buffer
	writer := gzip.NewWriter(&compressed)
	if _, err := writer.Write(data); err != nil {
		return "", err
	}
	if err := writer.Close(); err != nil {
		return "", err
	}
	return "<!-- keynope-assets version=1 base64:" + base64.StdEncoding.EncodeToString(compressed.Bytes()) + " -->", nil
}

func embeddedAssetPath(id string, asset DeckAsset) string {
	if len(asset.Frames) > 0 {
		return "keynope-asset:" + id + ".gif"
	}
	ext := ".png"
	if asset.MIME == "image/gif" {
		ext = ".gif"
	}
	if runtime.GOOS == "js" {
		return "keynope-asset:" + id + ext
	}
	return filepath.Join(imageCacheDirectory(), "embedded", id+ext)
}

func embeddedImageAsset(data []byte) (string, DeckAsset, string, error) {
	if len(data) == 0 || len(data) > 50<<20 {
		return "", DeckAsset{}, "", errors.New("image is empty or too large")
	}
	if bytes.HasPrefix(data, []byte("GIF8")) {
		if err := preflightGIFFrames(data); err != nil {
			return "", DeckAsset{}, "", err
		}
	}
	config, _, err := image.DecodeConfig(bytes.NewReader(data))
	if err != nil {
		return "", DeckAsset{}, "", fmt.Errorf("decode image header: %w", err)
	}
	if config.Width <= 0 || config.Height <= 0 || int64(config.Width)*int64(config.Height) > 32_000_000 {
		return "", DeckAsset{}, "", errors.New("image exceeds the 32 megapixel decoded size limit")
	}
	if animation, err := gif.DecodeAll(bytes.NewReader(data)); err == nil && len(animation.Image) > 1 {
		width, height := animation.Config.Width, animation.Config.Height
		if int64(width)*int64(height)*int64(len(animation.Image)) > 32_000_000 {
			return "", DeckAsset{}, "", errors.New("animation exceeds the 32 megapixel total decoded frame limit")
		}
		targetW, targetH := boundedImageSize(width, height, 384)
		decoded := decodeGIFAnimation(animation)
		asset := DeckAsset{MIME: "image/gif", Width: targetW, Height: targetH, LoopCount: animation.LoopCount}
		if targetW != width || targetH != height {
			asset.Source = &DeckAssetSource{MIME: "image/png", Width: width, Height: height}
		}
		storedBytes := 0
		for _, frame := range decoded {
			frameImage := frame.image
			if targetW != width || targetH != height {
				resized := image.NewNRGBA(image.Rect(0, 0, targetW, targetH))
				xdraw.CatmullRom.Scale(resized, resized.Bounds(), frame.image, frame.image.Bounds(), draw.Src, nil)
				frameImage = resized
			}
			var output bytes.Buffer
			if err := png.Encode(&output, frameImage); err != nil {
				return "", DeckAsset{}, "", err
			}
			delay := frame.delay
			if delay <= 0 {
				delay = 100 * time.Millisecond
			}
			asset.Frames = append(asset.Frames, DeckAssetFrame{Data: output.Bytes(), DelayMS: delay.Milliseconds()})
			storedBytes += output.Len()
			if asset.Source != nil {
				var source bytes.Buffer
				if err := png.Encode(&source, frame.image); err != nil {
					return "", DeckAsset{}, "", err
				}
				storedBytes += source.Len()
				asset.Source.Frames = append(asset.Source.Frames, DeckAssetFrame{Data: source.Bytes(), DelayMS: delay.Milliseconds()})
			}
			if storedBytes > 50<<20 {
				return "", DeckAsset{}, "", errors.New("animation exceeds the 50 MiB embedded storage limit")
			}
		}
		return makeAnimatedDeckAsset(asset)
	}
	decoded, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		return "", DeckAsset{}, "", fmt.Errorf("decode image: %w", err)
	}
	width, height := decoded.Bounds().Dx(), decoded.Bounds().Dy()
	targetW, targetH := boundedImageSize(width, height, 384)
	outputImage := image.Image(decoded)
	if targetW != width || targetH != height {
		resized := image.NewNRGBA(image.Rect(0, 0, targetW, targetH))
		xdraw.CatmullRom.Scale(resized, resized.Bounds(), decoded, decoded.Bounds(), draw.Src, nil)
		outputImage = resized
	}
	var output bytes.Buffer
	if err := png.Encode(&output, outputImage); err != nil {
		return "", DeckAsset{}, "", err
	}
	var source *DeckAssetSource
	if targetW != width || targetH != height {
		var original bytes.Buffer
		if err := png.Encode(&original, decoded); err != nil {
			return "", DeckAsset{}, "", err
		}
		if original.Len() > 50<<20 {
			return "", DeckAsset{}, "", errors.New("full-resolution image exceeds the 50 MiB storage limit")
		}
		source = &DeckAssetSource{MIME: "image/png", Width: width, Height: height, Data: original.Bytes()}
	}
	return makeDeckAssetWithSource(output.Bytes(), "image/png", targetW, targetH, source)
}

func makeAnimatedDeckAsset(asset DeckAsset) (string, DeckAsset, string, error) {
	if len(asset.Frames) < 2 {
		return "", DeckAsset{}, "", errors.New("animated image has fewer than two frames")
	}
	hash := sha256.New()
	fmt.Fprintf(hash, "%s:%dx%d:%d:", asset.MIME, asset.Width, asset.Height, asset.LoopCount)
	for _, frame := range asset.Frames {
		fmt.Fprintf(hash, "%d:", frame.DelayMS)
		_, _ = hash.Write(frame.Data)
	}
	if asset.Source != nil {
		encoded, err := json.Marshal(asset.Source)
		if err != nil {
			return "", DeckAsset{}, "", err
		}
		_, _ = hash.Write([]byte("\x00keynope-source\x00"))
		_, _ = hash.Write(encoded)
	}
	id := hex.EncodeToString(hash.Sum(nil))
	registerEmbeddedAnimatedAsset(id, asset)
	return id, asset, embeddedAssetPath(id, asset), nil
}

func boundedImageSize(width, height, maximum int) (int, int) {
	if width <= 0 || height <= 0 || maximum <= 0 || (width <= maximum && height <= maximum) {
		return width, height
	}
	scale := math.Min(float64(maximum)/float64(width), float64(maximum)/float64(height))
	return max(1, int(math.Round(float64(width)*scale))), max(1, int(math.Round(float64(height)*scale)))
}

func makeDeckAsset(data []byte, mime string, width, height int) (string, DeckAsset, string, error) {
	return makeDeckAssetWithSource(data, mime, width, height, nil)
}

func makeDeckAssetWithSource(data []byte, mime string, width, height int, source *DeckAssetSource) (string, DeckAsset, string, error) {
	hash := sha256.New()
	_, _ = hash.Write(data)
	if source != nil {
		_, _ = hash.Write([]byte("\x00keynope-source\x00"))
		_, _ = hash.Write(source.Data)
	}
	id := hex.EncodeToString(hash.Sum(nil))
	asset := DeckAsset{Source: source, MIME: mime, Width: width, Height: height, Data: append([]byte(nil), data...)}
	path := embeddedAssetPath(id, asset)
	registerEmbeddedStillAsset(id, asset)
	if runtime.GOOS == "js" {
		return id, asset, path, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", DeckAsset{}, "", err
	}
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return "", DeckAsset{}, "", err
	}
	return id, asset, path, nil
}

func materializeDeckAssets(deck *Deck) {
	if deck == nil || len(deck.Assets) == 0 {
		return
	}
	for id, asset := range deck.Assets {
		path := embeddedAssetPath(id, asset)
		if len(asset.Frames) > 0 {
			registerEmbeddedAnimatedAsset(id, asset)
			visitDeckImages(deck, func(element *Element) {
				if element.AssetID == id {
					element.Path = path
				}
			})
			continue
		}
		registerEmbeddedStillAsset(id, asset)
		if runtime.GOOS == "js" {
			visitDeckImages(deck, func(element *Element) {
				if element.AssetID == id {
					element.Path = path
				}
			})
			continue
		}
		if _, err := os.Stat(path); err != nil {
			if os.MkdirAll(filepath.Dir(path), 0o755) == nil {
				_ = os.WriteFile(path, asset.Data, 0o644)
			}
		}
		visitDeckImages(deck, func(element *Element) {
			if element.AssetID == id {
				element.Path = path
			}
		})
	}
}

func visitDeckImages(deck *Deck, visit func(*Element)) {
	if deck == nil || visit == nil {
		return
	}
	visitSlide := func(slide *Slide) {
		for index := range slide.Elements {
			if slide.Elements[index].Kind == "image" {
				visit(&slide.Elements[index])
			}
		}
	}
	for index := range deck.Slides {
		visitSlide(&deck.Slides[index])
	}
	visitSlide(&deck.Masters.Base.Slide)
	for index := range deck.Masters.Layouts {
		visitSlide(&deck.Masters.Layouts[index].Slide)
	}
}

func pruneUnusedDeckAssets(deck *Deck) {
	if deck == nil || len(deck.Assets) == 0 {
		return
	}
	used := map[string]bool{}
	visitDeckImages(deck, func(element *Element) {
		if element.AssetID != "" {
			used[element.AssetID] = true
		}
	})
	for id := range deck.Assets {
		if !used[id] {
			delete(deck.Assets, id)
		}
	}
}

func parseDeck(path string) (Deck, error) {
	parsedDeckElementOrderChanged = false
	data, err := os.ReadFile(path)
	if err != nil {
		return Deck{}, err
	}
	return parseDeckData(path, data)
}

func parseDeckData(path string, data []byte) (Deck, error) {
	parsedDeckElementOrderChanged = false
	text := string(data)
	var documentExtra *jsonExtensions
	if match := documentExtensionsRE.FindStringSubmatch(text); match != nil {
		var extensionErr error
		documentExtra, extensionErr = decodeExtensionComment(match)
		if extensionErr != nil {
			return Deck{}, extensionErr
		}
		text = documentExtensionsRE.ReplaceAllString(text, "")
	}
	appearance, text, diagnostics := recoverDeckAppearance(text)
	hideActivityQR := false
	if match := activityQRSettingRE.FindStringSubmatch(text); match != nil {
		hideActivityQR = match[1] == "off"
		text = activityQRSettingRE.ReplaceAllString(text, "")
	}
	tabs, text, err := decodeDeckTabs(text)
	if err != nil {
		return Deck{}, err
	}
	assets, remainingAssets, err := decodeDeckAssets(text)
	if err != nil {
		return Deck{}, err
	}
	text = remainingAssets
	// Retired bitmap/FIGlet payloads are not needed to migrate their text.
	// Strip the envelope without decompressing or allocating its glyph maps.
	hadRetiredFonts := keynopeFontsEnvelopeRE.MatchString(text)
	text = keynopeFontsEnvelopeRE.ReplaceAllString(text, "")
	if hadRetiredFonts {
		diagnostics = append(diagnostics, documentDiagnostic{Code: "retired-font-data", Message: "Converted retired bitmap/FIGlet text to supported TrueType text; the retired font artwork will be removed when saved."})
	}
	var malformedTextPayload bool
	text, malformedTextPayload = recoverTrueTypeEnvelopes(text)
	if malformedTextPayload {
		diagnostics = append(diagnostics, documentDiagnostic{Code: "text-payload-recovered", Message: "Ignored malformed encoded text metadata while preserving the rest of the slide."})
	}
	authoredTerminalWidth = 0
	authoredTerminalHeight = 0
	if match := keynopeMetaRE.FindStringSubmatch(text); match != nil {
		authoredTerminalWidth, _ = strconv.Atoi(match[1])
		authoredTerminalHeight, _ = strconv.Atoi(match[2])
		text = keynopeMetaRE.ReplaceAllString(text, "")
	}
	masters, remaining, err := decodeMasterDeckMetadata(text)
	if err != nil {
		return Deck{}, err
	}
	text = remaining
	base := filepath.Dir(path)
	resolveMasterDeckImagePaths(&masters, base)
	parsedDeckElementOrderChanged = elementOrderMappingChanged(canonicalizeSlideElementOrder(&masters.Base.Slide, authoredTerminalWidth, authoredTerminalHeight))
	for index := range masters.Layouts {
		parsedDeckElementOrderChanged = elementOrderMappingChanged(canonicalizeSlideElementOrder(&masters.Layouts[index].Slide, authoredTerminalWidth, authoredTerminalHeight)) || parsedDeckElementOrderChanged
	}
	var slides []Slide
	for _, part := range splitSlides(text) {
		slide := parseSlide(part, base)
		if slide.TabID != "" || len(slide.Elements) > 0 || slide.TTFSize > 0 || slide.TTFWidth > 0 || slide.EffectSet || slide.BackgroundSet || slide.FGSet || slide.BGSet || slide.HeaderFGSet || slide.Effect != "" || slide.Background != "" || slide.FG != "" || slide.BG != "" || slide.HeaderFG != "" || slide.Notes != "" || slide.LayoutID != "" || slide.PageNumber != "" || slide.Engagement != nil {
			parsedDeckElementOrderChanged = elementOrderMappingChanged(canonicalizeSlideElementOrder(&slide, authoredTerminalWidth, authoredTerminalHeight)) || parsedDeckElementOrderChanged
			slides = append(slides, slide)
		}
	}
	deck := Deck{Appearance: appearance, Diagnostics: diagnostics, Slides: slides, Masters: masters, Assets: assets, Tabs: tabs, HideActivityQR: hideActivityQR, Extra: documentExtra}
	if deckUsesRetiredTextMetadata(deck) && !hadRetiredFonts {
		deck.Diagnostics = append(deck.Diagnostics, documentDiagnostic{Code: "retired-text-data", Message: "Converted retired bitmap text settings to supported TrueType text; obsolete settings will be removed when saved."})
	}
	parsedDeckElementOrderChanged = ensureUniqueEngagementIDs(&deck) || parsedDeckElementOrderChanged
	syncSlideTabs(&deck)
	standardizeDeckText(&deck)
	materializeDeckAssets(&deck)
	return deck, nil
}

func ensureDefaultAuthoredSize() {
	if authoredTerminalWidth <= 0 || authoredTerminalHeight <= 0 {
		authoredTerminalWidth = defaultAuthoredTerminalWidth
		authoredTerminalHeight = defaultAuthoredTerminalHeight
	}
}

func serializeDeck(path string, deck Deck) ([]byte, error) {
	if authoredTerminalWidth <= 0 || authoredTerminalHeight <= 0 {
		authoredTerminalWidth, authoredTerminalHeight = terminalSize()
	}
	deck = cloneDeck(deck)
	syncSlideTabs(&deck)
	pruneUnusedDeckAssets(&deck)
	visitDeckImages(&deck, func(element *Element) {
		if element.AssetID != "" {
			element.Path = "keynope-asset:" + element.AssetID
		}
	})
	for index := range deck.Slides {
		canonicalizeSlideElementOrder(&deck.Slides[index], authoredTerminalWidth, authoredTerminalHeight)
	}
	canonicalizeSlideElementOrder(&deck.Masters.Base.Slide, authoredTerminalWidth, authoredTerminalHeight)
	for index := range deck.Masters.Layouts {
		canonicalizeSlideElementOrder(&deck.Masters.Layouts[index].Slide, authoredTerminalWidth, authoredTerminalHeight)
	}
	var out strings.Builder
	if metadata, err := encodeExtensionComment("document", deck.Extra); err != nil {
		return nil, err
	} else if metadata != "" {
		out.WriteString(metadata + "\n\n")
	}
	if metadata, err := encodeDeckAppearance(deck.Appearance); err != nil {
		return nil, err
	} else if metadata != "" {
		out.WriteString(metadata + "\n\n")
	}
	if deck.HideActivityQR {
		out.WriteString("<!-- keynope-activity-qr=off -->\n\n")
	}
	if len(deck.Tabs) > 0 {
		if err := validateDeckTabs(deck.Tabs); err != nil {
			return nil, err
		}
		metadata, err := json.Marshal(deck.Tabs)
		if err != nil {
			return nil, err
		}
		fmt.Fprintf(&out, "<!-- keynope-tabs version=1 base64:%s -->\n\n", base64.StdEncoding.EncodeToString(metadata))
	}
	if authoredTerminalWidth > 0 && authoredTerminalHeight > 0 {
		fmt.Fprintf(&out, "<!-- keynope width=%d height=%d -->\n\n", authoredTerminalWidth, authoredTerminalHeight)
	}
	if metadata, err := encodeDeckAssets(deck.Assets); err != nil {
		return nil, err
	} else if metadata != "" {
		out.WriteString(metadata)
		out.WriteString("\n\n")
	}
	if deckHasMasterData(deck.Masters) {
		metadata, err := encodeMasterDeckMetadataForPath(deck.Masters, path)
		if err != nil {
			return nil, err
		}
		out.WriteString(metadata)
		out.WriteString("\n\n")
	}
	for slideIndex, slide := range deck.Slides {
		if slideIndex > 0 {
			out.WriteString("\n---\n")
		}
		if metadata, err := encodeExtensionComment("slide", slide.Extra); err != nil {
			return nil, err
		} else if metadata != "" {
			out.WriteString(metadata)
			out.WriteByte('\n')
		}
		if slide.LayoutID != "" {
			fmt.Fprintf(&out, "<!-- layout=%s -->\n", slide.LayoutID)
		}
		if slide.TabID != "" {
			fmt.Fprintf(&out, "<!-- keynope-tab=%s -->\n", slide.TabID)
		}
		if slide.PageNumber != "" {
			fmt.Fprintf(&out, "<!-- page-number=%s -->\n", slide.PageNumber)
		}
		if metadata, err := encodeEngagementMetadata(slide.Engagement); err != nil {
			return nil, err
		} else if metadata != "" {
			out.WriteString(metadata)
			out.WriteByte('\n')
		}
		if metadata, err := encodeEngagementResult(slide.EngagementResult); err != nil {
			return nil, err
		} else if metadata != "" {
			out.WriteString(metadata)
			out.WriteByte('\n')
		}
		if slide.EffectSet || slide.Effect != "" {
			value := slide.Effect
			if value == "" {
				value = "none"
			}
			fmt.Fprintf(&out, "<!-- effect=%s -->\n", value)
		}
		if slide.BackgroundSet || slide.Background != "" {
			value := slide.Background
			if value == "" {
				value = "none"
			}
			fmt.Fprintf(&out, "<!-- background=%s -->\n", value)
		}
		if slide.Notes != "" {
			fmt.Fprintf(&out, "<!-- notes=base64:%s -->\n", base64.StdEncoding.EncodeToString([]byte(slide.Notes)))
		}
		style := slideStyleComment(slide)
		if style != "" {
			out.WriteString(style)
			out.WriteByte('\n')
		}
		if (slide.LayoutID != "" || slide.PageNumber != "" || slide.Engagement != nil || slide.EffectSet || slide.Effect != "" || slide.BackgroundSet || slide.Background != "" || slide.Notes != "" || style != "") && len(slide.Elements) > 0 {
			out.WriteByte('\n')
		}
		for elementIndex, element := range slide.Elements {
			if element.Placeholder && element.MasterSlotID == "" {
				continue
			}
			if elementIndex > 0 {
				out.WriteByte('\n')
			}
			if metadata, err := encodeExtensionComment("element", element.Extra); err != nil {
				return nil, err
			} else if metadata != "" {
				out.WriteString(metadata)
				out.WriteByte('\n')
			}
			if element.MasterSlotID != "" {
				if element.Placeholder {
					fmt.Fprintf(&out, "<!-- master-slot=%s placeholder=true -->\n", element.MasterSlotID)
				} else {
					fmt.Fprintf(&out, "<!-- master-slot=%s -->\n", element.MasterSlotID)
				}
			}
			if element.ID != "" {
				element.Query = setQueryValue(element.Query, "element-id", element.ID)
			}
			if (element.Kind != "image" || element.Placeholder) && element.Query != "" {
				fmt.Fprintf(&out, "<!-- %s -->\n", placementCommentText(element.Query))
			}
			if element.Placeholder && element.MasterSlotID != "" {
				out.WriteString("Placeholder")
				out.WriteByte('\n')
				continue
			}
			if isTrueType(element) && (element.Text == "" || strings.Contains(element.Text, "\n") || strings.ContainsAny(element.Text, "`<>#[]") || strings.HasPrefix(element.Text, "-") || strings.TrimSpace(element.Text) != element.Text) {
				level := ""
				if element.Kind == "heading" {
					level = fmt.Sprintf(" level=%d", max(1, min(2, element.Level)))
				}
				fmt.Fprintf(&out, "<!-- truetype-text=base64:%s kind=%s%s -->\n", base64.StdEncoding.EncodeToString([]byte(element.Text)), element.Kind, level)
				continue
			}
			switch element.Kind {
			case "connector":
				out.WriteString("[connector]\n")
			case "heading":
				if element.Level == 1 {
					fmt.Fprintf(&out, "# %s\n", element.Text)
				} else {
					fmt.Fprintf(&out, "## %s\n", element.Text)
				}
			case "bullet":
				for _, item := range splitBulletListItems(normalizeBulletText(element.Text), false) {
					fmt.Fprintf(&out, "- %s\n", item.Text)
					for _, continuation := range item.Continuations {
						fmt.Fprintf(&out, "  %s\n", continuation)
					}
				}
			case "code":
				out.WriteString("```\n")
				out.WriteString(element.Text)
				if !strings.HasSuffix(element.Text, "\n") {
					out.WriteByte('\n')
				}
				out.WriteString("```\n")
			case "image":
				src := element.Path
				if element.AssetID != "" {
					src = "keynope-asset:" + element.AssetID
				}
				if !isExternalImageSource(element.Path) {
					if rel, err := filepath.Rel(filepath.Dir(path), element.Path); err == nil && !strings.HasPrefix(rel, "..") {
						src = rel
					}
				}
				if element.Query != "" {
					src += "?" + element.Query
				}
				fmt.Fprintf(&out, "![image](%s)\n", src)
			case "shape":
				shape := shapeName(element)
				fmt.Fprintf(&out, "[shape:%s]\n", shape)
			case "text-image":
				out.WriteString(element.Text)
				out.WriteByte('\n')
			default:
				out.WriteString(element.Text)
				out.WriteByte('\n')
			}
		}
	}
	return []byte(out.String()), nil
}

func canonicalizeSlideElementOrder(slide *Slide, width, height int) []int {
	if slide == nil || len(slide.Elements) < 2 {
		return nil
	}
	width, height = authoredRenderSize(width, height)
	if width <= 0 {
		width = defaultAuthoredTerminalWidth
	}
	if height <= 0 {
		height = defaultAuthoredTerminalHeight
	}
	type position struct {
		element Element
		old     int
		top     int
		left    int
		name    string
	}
	positions := make([]position, len(slide.Elements))
	for index, element := range slide.Elements {
		positions[index] = position{element: element, old: index, top: int(^uint(0) >> 1), left: int(^uint(0) >> 1), name: elementSortName(element)}
	}
	// Visibility controls painting, not reading order. Measure hidden objects as
	// well so toggling visibility cannot move them to the end of the Markdown.
	measurement := *slide
	if len(hiddenSlideObjects(*slide)) > 0 {
		measurement = cloneSlide(*slide)
		for i := range measurement.Elements {
			measurement.Elements[i].Query = removeImageQueryKeys(measurement.Elements[i].Query, "object-hidden")
		}
	}
	for _, line := range layout(measurement, width, height) {
		if line.Element < 0 || line.Element >= len(positions) || line.Role == "outline" {
			continue
		}
		item := &positions[line.Element]
		if line.Row < item.top || line.Row == item.top && line.Col < item.left {
			item.top, item.left = line.Row, line.Col
		}
	}
	sort.SliceStable(positions, func(i, j int) bool {
		if positions[i].top != positions[j].top {
			return positions[i].top < positions[j].top
		}
		if positions[i].left != positions[j].left {
			return positions[i].left < positions[j].left
		}
		if positions[i].name != positions[j].name {
			return positions[i].name < positions[j].name
		}
		return false
	})
	oldToNew := make([]int, len(positions))
	for newIndex, item := range positions {
		slide.Elements[newIndex] = item.element
		oldToNew[item.old] = newIndex
	}
	return oldToNew
}

func elementSortName(element Element) string {
	name := strings.TrimSpace(element.Text)
	if name == "" {
		name = strings.TrimSpace(element.Path)
	}
	if name == "" && element.Kind == "shape" {
		name = shapeName(element)
	}
	return strings.ToLower(name)
}

func elementOrderMappingChanged(oldToNew []int) bool {
	for oldIndex, newIndex := range oldToNew {
		if oldIndex != newIndex {
			return true
		}
	}
	return false
}

type bulletListItem struct {
	Text          string
	Continuations []string
}

func splitBulletListItems(text string, keepEmpty bool) []bulletListItem {
	lines := strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")
	items := make([]bulletListItem, 0, len(lines))
	for _, line := range lines {
		continuation := len(line) > 0 && (line[0] == ' ' || line[0] == '\t')
		value := strings.TrimSpace(line)
		if continuation && len(items) > 0 {
			if value != "" || keepEmpty {
				items[len(items)-1].Continuations = append(items[len(items)-1].Continuations, value)
			}
			continue
		}
		if value == "" && !keepEmpty {
			continue
		}
		items = append(items, bulletListItem{Text: value})
	}
	return items
}

func normalizeBulletText(text string) string {
	items := splitBulletListItems(text, false)
	lines := make([]string, 0, len(items))
	for _, item := range items {
		if item.Text == "" {
			continue
		}
		lines = append(lines, item.Text)
		for _, continuation := range item.Continuations {
			if continuation != "" {
				lines = append(lines, "  "+continuation)
			}
		}
	}
	return strings.Join(lines, "\n")
}

type noticeLevel int

const (
	noticeSuccess noticeLevel = iota
	noticeError
)

type uiNotice struct {
	Text      string
	Level     noticeLevel
	ExpiresAt time.Time
}

func setUINoticeLevel(message string, level noticeLevel) {
	uiNoticeMu.Lock()
	defer uiNoticeMu.Unlock()
	message = strings.TrimSpace(message)
	if message == "" {
		activeUINotice = uiNotice{}
		return
	}
	duration := 2500 * time.Millisecond
	if level == noticeError {
		duration = 6 * time.Second
	}
	activeUINotice = uiNotice{Text: message, Level: level, ExpiresAt: time.Now().Add(duration)}
}

func setUIError(message string) {
	setUINoticeLevel(message, noticeError)
}

func exportHTMLDocument(deckPath string, slides []Slide, cols, rows int, preserved preservedExportHead, presenter bool) (string, error) {
	return exportProjectedHTML(projectExportDeck(deckPath, slides, cols, rows, presenter), preserved, presenter)
}

func projectExportDeck(deckPath string, slides []Slide, cols, rows int, presenter bool) exportDeck {
	cols = max(20, cols)
	rows = max(10, rows)
	deck := exportDeck{
		Cols:   cols,
		Rows:   rows,
		Source: filepath.Base(deckPath),
	}
	for slideIndex, slide := range slides {
		if !presenter {
			slide = standaloneExportSlide(slide, slideIndex)
		}
		pages := exportSlidePages(slide, slideIndex, len(slides), cols, rows)
		if !presenter {
			// Downloaded decks are presentation snapshots, not workshop hosts.
			// Definitions can contain correct answers and live session codes.
			for i := range pages {
				pages[i].Engagement = nil
			}
		}
		deck.Pages = append(deck.Pages, pages...)
	}
	return deck
}

func exportProjectedHTML(deck exportDeck, preserved preservedExportHead, presenter bool) (string, error) {
	if preserved.Title == "" {
		title := strings.TrimSuffix(strings.TrimSpace(deck.Source), filepath.Ext(deck.Source))
		if title == "" {
			title = "Keynope Presentation"
		}
		preserved.Title = "<title>" + stdhtml.EscapeString(title) + "</title>"
	}
	payload, err := json.Marshal(deck)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	out.WriteString(exportHTMLPrefix(preserved, presenter))
	for _, page := range deck.Pages {
		if page.Scene != nil {
			out.WriteString("<style data-keynope-modern-fonts>" + modernFontsCSS() + "</style>\n")
			break
		}
	}
	out.WriteString("\n<script id=\"keynope-data\" type=\"application/json\">")
	out.WriteString(string(payload))
	out.WriteString("</script>\n")
	out.WriteString(exportHTMLSuffix())
	return out.String(), nil
}

func exportSlidePages(slide Slide, slideIndex, slideCount, cols, rows int) []exportPage {
	return exportSlidePagesMode(slide, slideIndex, slideCount, cols, rows, false)
}

func exportSlidePagesFrozen(slide Slide, slideIndex, slideCount, cols, rows int) []exportPage {
	return exportSlidePagesMode(slide, slideIndex, slideCount, cols, rows, true)
}

func exportSlidePagesMode(slide Slide, slideIndex, slideCount, cols, rows int, frozenImages bool) []exportPage {
	if slide.ModernScene != nil {
		lines := layout(withTrueTypeDefaults(slide), cols, rows)
		return []exportPage{{Scene: slide.ModernScene, ShapePorts: slideShapePorts(slide, lines, cols, rows), Connectors: slideShapeConnectors(slide, lines, cols, rows), HideActivityQR: slide.HideActivityQR, TabOnly: slide.TabID != "", Slide: slideIndex, PageCount: 1, SlideCount: slideCount, Effect: slide.Effect, Background: slide.Background, BackgroundLines: staticBackgroundExportLines(slide.Background, cols, rows, ansiCSSColour(slideFG(slide)), slideBG(slide)), FG: ansiCSSColour(slideFG(slide)), BG: slide.ModernScene.Background, HeaderFG: ansiCSSColour(slideHeaderFG(slide)), Lines: []exportLine{}, HideChromePageNumber: true, Engagement: cloneEngagement(slide.Engagement)}}
	}
	slide = withTrueTypeDefaults(slide)
	pageCount := slidePageCount(slide, cols, rows)
	pages := make([]exportPage, 0, pageCount)
	for page := 0; page < pageCount; page++ {
		lines := displayLines(slide, cols, rows, page)
		var contentFrames []exportContentFrame
		if !frozenImages {
			contentFrames = exportContentFrames(slide, page, cols, rows, slideCount)
		}
		pages = append(pages, exportPage{
			HideActivityQR:       slide.HideActivityQR,
			ShapePorts:           slideShapePorts(slide, lines, cols, rows),
			Connectors:           slideShapeConnectors(slide, lines, cols, rows),
			TabOnly:              slide.TabID != "",
			Slide:                slideIndex,
			Page:                 page,
			PageCount:            pageCount,
			SlideCount:           slideCount,
			Effect:               slide.Effect,
			Background:           slide.Background,
			BackgroundLines:      staticBackgroundExportLines(slide.Background, cols, rows, ansiCSSColour(slideFG(slide)), slideBG(slide)),
			Transparency:         transparentShapeExportLines(lines, cols, rows, slide),
			ContentFrames:        contentFrames,
			FG:                   ansiCSSColour(slideFG(slide)),
			BG:                   ansiCSSColour(slideBG(slide)),
			HeaderFG:             ansiCSSColour(slideHeaderFG(slide)),
			TTFSize:              slide.TTFSize,
			TTFWidth:             slide.TTFWidth,
			Lines:                exportLines(lines, slide, cols, rows, slideCount),
			HideChromePageNumber: slide.PageNumber != "",
			Engagement:           cloneEngagement(slide.Engagement),
		})
	}
	return pages
}

func startPresenterCompanion(deckPath string, slides []Slide, cols, rows int) (*presenterCompanion, error) {
	html, pages, err := projectPresenterDocument(deckPath, slides, cols, rows)
	if err != nil {
		return nil, err
	}
	tokenBytes := make([]byte, 32)
	if _, err := cryptorand.Read(tokenBytes); err != nil {
		return nil, fmt.Errorf("create companion token: %w", err)
	}
	companion := &presenterCompanion{
		html: html, pages: pages, frames: map[chan presenterTerminalFrame]<-chan struct{}{},
		token: hex.EncodeToString(tokenBytes),
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		html, err := companion.htmlSnapshot()
		if err != nil {
			http.Error(w, "could not prepare presentation", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = io.WriteString(w, html)
	})
	mux.HandleFunc("/state", func(w http.ResponseWriter, r *http.Request) {
		companion.mu.RLock()
		state := companion.state
		companion.mu.RUnlock()
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(w).Encode(state)
	})
	mux.HandleFunc("/slides", func(w http.ResponseWriter, r *http.Request) {
		pages, version := companion.slideSnapshot()
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(w).Encode(struct {
			Pages   []exportPage `json:"pages"`
			Version int64        `json:"version"`
		}{pages, version})
	})
	mux.HandleFunc("/slide", func(w http.ResponseWriter, r *http.Request) {
		raw := r.URL.Query().Get("index")
		index, err := strconv.Atoi(raw)
		if err != nil {
			http.Error(w, "invalid slide index", http.StatusBadRequest)
			return
		}
		pages, version := companion.slideSnapshotAt(index)
		if pages == nil {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(w).Encode(struct {
			Pages   []exportPage `json:"pages"`
			Version int64        `json:"version"`
		}{pages, version})
	})
	mux.HandleFunc("/terminal-frame", func(w http.ResponseWriter, r *http.Request) {
		companion.mu.RLock()
		frame := companion.frame
		companion.mu.RUnlock()
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		_ = json.NewEncoder(w).Encode(frame)
	})
	mux.HandleFunc("/terminal-events", companion.handleTerminalEvents)
	mux.HandleFunc("/key", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		var event KeyEvent
		if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
			http.Error(w, "invalid key event", http.StatusBadRequest)
			return
		}
		if event.Action == "" {
			http.Error(w, "missing action", http.StatusBadRequest)
			return
		}
		select {
		case remoteKeyEvents <- event:
			w.WriteHeader(http.StatusNoContent)
		default:
			http.Error(w, "key queue full", http.StatusTooManyRequests)
		}
	})
	mux.HandleFunc("/presenter-status", companion.handlePresenterStatus)
	mux.HandleFunc("/engagement", companion.handleEngagement)
	if activeNativeEditor != nil {
		mux.HandleFunc("/api/editor/state", activeNativeEditor.handleState)
		mux.HandleFunc("/api/editor/scene", activeNativeEditor.handleScene)
		mux.HandleFunc("/api/editor/scene-fonts", activeNativeEditor.handleSceneFonts)
		mux.HandleFunc("/api/editor/action", activeNativeEditor.handleAction)
		mux.HandleFunc("/api/editor/preview", activeNativeEditor.handlePreview)
		mux.HandleFunc("/api/editor/connector-preview", activeNativeEditor.handleConnectorPreview)
		mux.HandleFunc("/api/editor/connector-draft", activeNativeEditor.handleConnectorDraft)
		mux.HandleFunc("/api/editor/fit-text", activeNativeEditor.handleFitText)
		mux.HandleFunc("/api/editor/normalize-text-kind", activeNativeEditor.handleNormalizeTextKind)
		mux.HandleFunc("/api/editor/emojis", activeNativeEditor.handleEmojiCatalog)
		mux.HandleFunc("/api/editor/emoji-text-fonts", activeNativeEditor.handleEmojiTextFonts)
		mux.HandleFunc("/api/editor/shape-draft", activeNativeEditor.handleShapeDraft)
		mux.HandleFunc("/api/editor/media-draft", activeNativeEditor.handleMediaDraft)
		mux.HandleFunc("/api/editor/activity-qr", activeNativeEditor.handleActivityQR)
		mux.HandleFunc("/api/editor/workspace", activeNativeEditor.handleWorkspace)
		mux.HandleFunc("/api/editor/upload", activeNativeEditor.handleUpload)
		mux.HandleFunc("/api/editor/document", activeNativeEditor.handleDocument)
		mux.HandleFunc("/api/editor/participant-page", activeNativeEditor.handleParticipantPage)
		mux.HandleFunc("/api/editor/export-document", activeNativeEditor.handleExportDocument)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return nil, err
	}
	companion.url = "http://" + listener.Addr().String() + "/?token=" + url.QueryEscape(companion.token)
	companion.server = &http.Server{Handler: companion.authorized(mux)}
	go func() {
		if err := companion.server.Serve(listener); err != nil && err != http.ErrServerClosed {
			fmt.Fprintf(os.Stderr, "presenter companion stopped: %v\n", err)
		}
	}()
	companion.mu.Lock()
	companion.helper = true
	companion.target = "none"
	companion.mu.Unlock()
	fmt.Println("KEYNOPE_URL=" + companion.url)
	return companion, nil
}

func (p *presenterCompanion) authorized(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authorized := false
		if token := r.URL.Query().Get("token"); token != "" && token == p.token {
			authorized = true
			http.SetCookie(w, &http.Cookie{
				Name: "keynope_session", Value: p.token, Path: "/", HttpOnly: true,
				SameSite: http.SameSiteStrictMode,
			})
		}
		if cookie, err := r.Cookie("keynope_session"); err == nil && cookie.Value == p.token {
			authorized = true
		}
		if !authorized {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			origin := r.Header.Get("Origin")
			if origin != "" {
				parsed, err := url.Parse(origin)
				if err != nil || parsed.Host != r.Host {
					http.Error(w, "invalid origin", http.StatusForbidden)
					return
				}
			}
		}
		next.ServeHTTP(w, r)
	})
}

func (p *presenterCompanion) Status() (available bool, target string, live bool) {
	if p == nil {
		return false, "none", false
	}
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.helper, p.target, p.state.Presenting
}

// Visiting a tab temporarily suppresses broadcasting, not the presenter's
// chosen play/pause state. Returning to a normal slide resumes that state.
func (p *presenterCompanion) presentationEnabled() bool {
	p.mu.RLock()
	defer p.mu.RUnlock()
	if p.helper {
		return (p.target == "main" || p.target == "external") && !p.paused
	}
	return p.state.Presenting
}

func (p *presenterCompanion) Position() (slide, page int) {
	if p == nil {
		return 0, 0
	}
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.state.Slide, p.state.Page
}

func (p *presenterCompanion) handlePresenterStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var status struct {
		Mode   string `json:"mode"`
		Paused bool   `json:"paused"`
	}
	if err := json.NewDecoder(r.Body).Decode(&status); err != nil {
		http.Error(w, "invalid presenter status", http.StatusBadRequest)
		return
	}
	if status.Mode != "none" && status.Mode != "main" && status.Mode != "external" {
		http.Error(w, "invalid presenter mode", http.StatusBadRequest)
		return
	}
	p.mu.Lock()
	p.target = status.Mode
	p.paused = status.Paused
	p.helper = true
	if nativeAppModeActive {
		presenting := status.Mode != "none" && !status.Paused
		changed := false
		if p.state.Presenting != presenting {
			p.state.Presenting = presenting
			changed = true
		}
		if status.Mode == "none" && p.state.Engagement != nil {
			p.state.Engagement = nil
			changed = true
		}
		if changed {
			p.state.Version++
		}
	}
	p.mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

func (p *presenterCompanion) handleEngagement(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var runtime *EngagementRuntimeState
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 256<<10)).Decode(&runtime); err != nil {
		http.Error(w, "invalid engagement state", http.StatusBadRequest)
		return
	}
	if runtime != nil {
		definition, err := normalizeEngagement(runtime.Definition)
		if err != nil || runtime.Slide < 0 || runtime.Phase < 0 || runtime.Phase >= 5 || len(runtime.Ideas) > 200 {
			http.Error(w, "invalid engagement state", http.StatusBadRequest)
			return
		}
		runtime.Definition = definition
		runtime.Ideas = cleanEngagementItems(runtime.Ideas)
		if len(runtime.Counts) > 12 || len(runtime.Assignments) > 40 || len(runtime.Respondents) > 200 || len(runtime.Attributions) > 200 || len(runtime.Groups) > 13 {
			http.Error(w, "invalid engagement state", http.StatusBadRequest)
			return
		}
		runtime.Respondents = cleanEngagementItems(runtime.Respondents)
	}
	p.mu.Lock()
	p.state.Engagement = cloneEngagementRuntime(runtime)
	p.state.Version++
	p.mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

func (p *presenterCompanion) handleTerminalEvents(w http.ResponseWriter, r *http.Request) {
	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "streaming unavailable", http.StatusInternalServerError)
		return
	}
	updates := make(chan presenterTerminalFrame, 64)
	p.mu.Lock()
	p.frames[updates] = r.Context().Done()
	initial := p.frame
	p.mu.Unlock()
	defer func() {
		p.mu.Lock()
		delete(p.frames, updates)
		p.mu.Unlock()
	}()
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Connection", "keep-alive")
	writeFrame := func(frame presenterTerminalFrame) bool {
		payload, err := json.Marshal(frame)
		if err != nil {
			return false
		}
		if _, err := fmt.Fprintf(w, "id: %d\ndata: %s\n\n", frame.Version, payload); err != nil {
			return false
		}
		flusher.Flush()
		return true
	}
	if !writeFrame(initial) {
		return
	}
	for {
		select {
		case frame := <-updates:
			if !writeFrame(frame) {
				return
			}
		case <-r.Context().Done():
			return
		}
	}
}

func (p *presenterCompanion) slideSnapshot() ([]exportPage, int64) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.slidePagesLocked(), p.state.DeckVersion
}

func (p *presenterCompanion) slideSnapshotAt(index int) ([]exportPage, int64) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return append([]exportPage(nil), p.pages[index]...), p.state.DeckVersion
}

// Caller holds p.mu for reading. Page payloads are immutable once published.
func (p *presenterCompanion) slidePagesLocked() []exportPage {
	indices := make([]int, 0, len(p.pages))
	for index := range p.pages {
		indices = append(indices, index)
	}
	sort.Ints(indices)
	pages := make([]exportPage, 0)
	for _, index := range indices {
		pages = append(pages, p.pages[index]...)
	}
	return pages
}

func (p *presenterCompanion) Refresh(deckPath string, slides []Slide, cols, rows int) error {
	if p == nil {
		return nil
	}
	seq := p.beginFullRefresh(deckPath)
	html, pages, err := projectPresenterDocument(deckPath, slides, cols, rows)
	if err != nil {
		return err
	}
	p.publishFullRefresh(seq, html, pages)
	return nil
}

func (p *presenterCompanion) RefreshAllAsync(deckPath string, slides []Slide, cols, rows int) {
	if p == nil {
		return
	}
	slides = cloneSlides(slides)
	seq := p.beginFullRefresh(deckPath)
	go p.renderFullRefresh(seq, deckPath, slides, cols, rows)
}

func (p *presenterCompanion) RefreshActiveSlideAsync(slides []Slide, cols, rows int) {
	if p == nil {
		return
	}
	p.mu.Lock()
	slideIndex := p.state.Slide
	if slideIndex < 0 || slideIndex >= len(slides) {
		p.mu.Unlock()
		return
	}
	p.seq++
	seq := p.seq
	if p.fullPending || (p.slidePending && p.pendingSlide != slideIndex) {
		p.fullPending, p.slidePending = true, false
		// A newer local edit cannot discard a pending deck-wide change (such
		// as a master edit). Render its latest complete snapshot instead.
		deckPath := p.refreshPath
		p.mu.Unlock()
		go p.renderFullRefresh(seq, deckPath, cloneSlides(slides), cols, rows)
		return
	}
	p.slidePending, p.pendingSlide = true, slideIndex
	p.mu.Unlock()
	slide := cloneSlide(slides[slideIndex])
	slideCount := len(slides)
	go func() {
		time.Sleep(80 * time.Millisecond)
		p.mu.RLock()
		stale := seq != p.seq
		p.mu.RUnlock()
		if stale {
			return
		}
		pages := exportSlidePages(slide, slideIndex, slideCount, cols, rows)
		p.mu.Lock()
		defer p.mu.Unlock()
		if seq != p.seq {
			return
		}
		if p.pages == nil {
			p.pages = map[int][]exportPage{}
		}
		p.pages[slideIndex] = pages
		p.slidePending = false
		p.state.DeckVersion++
		p.state.DeckSlide = slideIndex
		p.state.Version++
	}()
}

func (p *presenterCompanion) Update(slide, page int, presenting bool, deckState *EditState) {
	if p == nil {
		return
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	timerMode, timerInput, timerEndMS := p.state.TimerMode, p.state.TimerInput, p.state.TimerEndMS
	if deckState != nil {
		timerMode = deckState.TimerMode
		timerInput = deckState.TimerInput
		if !deckState.TimerDeadline.IsZero() {
			timerEndMS = deckState.TimerDeadline.UnixMilli()
		}
	}
	if p.state.Slide == slide && p.state.Page == page && p.state.Presenting == presenting && p.state.TimerMode == timerMode && p.state.TimerInput == timerInput && p.state.TimerEndMS == timerEndMS {
		return
	}
	p.state.Slide = slide
	p.state.Page = page
	p.state.Presenting = presenting
	p.state.TimerMode = timerMode
	p.state.TimerInput = timerInput
	p.state.TimerEndMS = timerEndMS
	p.state.Version++
}

func (p *presenterCompanion) StartTimer(duration time.Duration) {
	if p == nil || duration <= 0 {
		return
	}
	p.mu.Lock()
	p.state.TimerMode = "running"
	p.state.TimerInput = ""
	p.state.TimerEndMS = time.Now().Add(duration).UnixMilli()
	p.state.Version++
	p.mu.Unlock()
}

func (p *presenterCompanion) StopTimer() {
	if p == nil {
		return
	}
	p.mu.Lock()
	p.state.TimerMode = ""
	p.state.TimerInput = ""
	p.state.TimerEndMS = 0
	p.state.Version++
	p.mu.Unlock()
}

func (p *presenterCompanion) PublishTerminalFrame(frame string, cols, rows int) {
	if p == nil || cols <= 0 || rows <= 0 || frame == "" {
		return
	}
	p.mu.Lock()
	p.frame.Version++
	p.frame.Cols = cols
	p.frame.Rows = rows
	p.frame.Lines = nil
	p.frame.ANSI = frame
	update := p.frame
	subscribers := make(map[chan presenterTerminalFrame]<-chan struct{}, len(p.frames))
	for subscriber, done := range p.frames {
		subscribers[subscriber] = done
	}
	p.mu.Unlock()
	for subscriber, done := range subscribers {
		select {
		case subscriber <- update:
		case <-done:
		}
	}
}

func (p *presenterCompanion) Close() {
	if p == nil || p.server == nil {
		return
	}
	_ = p.server.Close()
}

type preservedExportHead struct {
	Title   string
	Metas   []string
	Scripts []string
}

const exportAnimationTimelineLimit = 30 * time.Second

func exportContentFrames(slide Slide, page, width, height, slideCount int) []exportContentFrame {
	if !slideHasAnimatedImage(slide) {
		return nil
	}
	timeline := exportAnimationTimeline(slide)
	if len(timeline) < 2 {
		return nil
	}
	exportImageAnimationMu.Lock()
	defer exportImageAnimationMu.Unlock()
	frames := make([]exportContentFrame, 0, len(timeline)-1)
	previousLines := []exportLine(nil)
	previousSignature := ""
	previous := exportImageAnimationPosition
	defer func() { exportImageAnimationPosition = previous }()
	for index := 0; index < len(timeline)-1; index++ {
		position := timeline[index]
		delay := timeline[index+1] - position
		if delay <= 0 {
			continue
		}
		exportImageAnimationPosition = &position
		lines := displayLines(slide, width, height, page)
		exported := exportLines(lines, slide, width, height, slideCount)
		signature := exportFrameSignature(exported)
		if len(frames) > 0 && signature == previousSignature {
			frames[len(frames)-1].DelayMS += delay.Milliseconds()
			continue
		}
		if len(frames) == 0 {
			frames = append(frames, exportContentFrame{DelayMS: delay.Milliseconds(), Full: true, Lines: exported})
		} else {
			clear, update := exportLineDelta(previousLines, exported)
			frames = append(frames, exportContentFrame{DelayMS: delay.Milliseconds(), Clear: clear, Update: update})
		}
		previousLines = exported
		previousSignature = signature
	}
	return frames
}

func exportAnimationTimeline(slide Slide) []time.Duration {
	var animations [][]time.Duration
	seen := map[string]bool{}
	for _, element := range slide.Elements {
		if element.Kind != "image" || seen[element.Path] {
			continue
		}
		ext := strings.ToLower(filepath.Ext(element.Path))
		if ext != ".gif" && ext != ".webp" {
			continue
		}
		seen[element.Path] = true
		decoded := decodeImageFrames(element.Path)
		if len(decoded) < 2 {
			continue
		}
		delays := make([]time.Duration, 0, len(decoded))
		for _, frame := range decoded {
			delay := frame.delay
			if delay <= 0 {
				delay = 100 * time.Millisecond
			}
			delays = append(delays, delay)
		}
		animations = append(animations, delays)
	}
	if len(animations) == 0 {
		return nil
	}
	cycle := animationDuration(animations[0])
	for _, animation := range animations[1:] {
		cycle = durationLCM(cycle, animationDuration(animation), exportAnimationTimelineLimit)
	}
	if cycle <= 0 {
		return nil
	}
	if cycle > exportAnimationTimelineLimit {
		cycle = exportAnimationTimelineLimit
	}
	boundaries := map[time.Duration]bool{0: true, cycle: true}
	for _, animation := range animations {
		total := animationDuration(animation)
		if total <= 0 {
			continue
		}
		for start := time.Duration(0); start < cycle; start += total {
			position := start
			for _, delay := range animation {
				if position >= cycle {
					break
				}
				boundaries[position] = true
				position += delay
			}
		}
	}
	timeline := make([]time.Duration, 0, len(boundaries))
	for boundary := range boundaries {
		timeline = append(timeline, boundary)
	}
	sort.Slice(timeline, func(i, j int) bool { return timeline[i] < timeline[j] })
	return timeline
}

func animationDuration(delays []time.Duration) time.Duration {
	var total time.Duration
	for _, delay := range delays {
		total += delay
	}
	return total
}

func durationLCM(left, right, limit time.Duration) time.Duration {
	if left <= 0 {
		return right
	}
	if right <= 0 {
		return left
	}
	leftMS := left.Milliseconds()
	rightMS := right.Milliseconds()
	gcd := leftMS
	for value := rightMS; value != 0; {
		gcd, value = value, gcd%value
	}
	if gcd <= 0 || leftMS/gcd > limit.Milliseconds()/rightMS {
		return limit + time.Millisecond
	}
	return time.Duration(leftMS/gcd*rightMS) * time.Millisecond
}

func exportLineDelta(previous, current []exportLine) ([]string, []exportLine) {
	prev := exportLineMap(previous)
	next := exportLineMap(current)
	var clear []string
	var update []exportLine
	for key := range prev {
		if _, ok := next[key]; !ok {
			clear = append(clear, key)
		}
	}
	for key, line := range next {
		if exportLineValue(prev[key]) != exportLineValue(line) {
			update = append(update, line)
		}
	}
	sort.Strings(clear)
	sort.Slice(update, func(i, j int) bool {
		if update[i].Row != update[j].Row {
			return update[i].Row < update[j].Row
		}
		return lineFirstCol(update[i]) < lineFirstCol(update[j])
	})
	return clear, update
}

func exportLineMap(lines []exportLine) map[string]exportLine {
	out := map[string]exportLine{}
	for _, line := range lines {
		out[exportLineKey(line)] = line
	}
	return out
}

func exportLineKey(line exportLine) string {
	return fmt.Sprintf("%d:%d:%d:%s", line.Row, lineFirstCol(line), line.Element, line.Role)
}

func lineFirstCol(line exportLine) int {
	if len(line.Parts) == 0 {
		return line.Col
	}
	return line.Parts[0].Col
}

func exportLineValue(line exportLine) string {
	data, err := json.Marshal(line)
	if err != nil {
		return ""
	}
	return string(data)
}

func exportFrameSignature(lines []exportLine) string {
	data, err := json.Marshal(lines)
	if err != nil {
		return ""
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func drawEffectFrame(name string, width, height, frame int, matrix *matrixEffect, stars *starsEffect, fireworks *burstEffect, background string) {
	effectFrame := captureTerminalOutput(func() {
		drawEffectFrameRaw(name, width, height, frame, matrix, stars, fireworks)
	})
	termPrint(applyANSIBackground(effectFrame, background))
}

func drawEffectFrameRaw(name string, width, height, frame int, matrix *matrixEffect, stars *starsEffect, fireworks *burstEffect) {
	switch name {
	case "matrix":
		matrix.draw(frame)
	case "stars":
		stars.draw()
	case "plasma":
		drawPlasma(width, height, frame)
	case "glitch":
		drawGlitch(width, height, frame)
	case "digital-snow":
		drawDigitalSnow(name, width, height, frame)
	case "radar":
		drawRadar(width, height, frame)
	case "neural":
		drawNeural(width, height, frame)
	case "circuit":
		drawCircuit(width, height, frame)
	case "data-storm":
		drawDataStorm(width, height, frame)
	case "flame":
		drawFlame(width, height, frame)
	case "warp":
		drawWarp(width, height, frame)
	case "scanline":
		drawScanline(width, height, frame)
	default:
		fireworks.draw(frame)
	}
}

func applyANSIBackground(frame, background string) string {
	if frame == "" || background == "" {
		return frame
	}
	var out strings.Builder
	out.Grow(len(frame) + len(background)*8)
	out.WriteString("\033[")
	out.WriteString(background)
	out.WriteByte('m')
	for index := 0; index < len(frame); {
		if frame[index] != '\033' || index+1 >= len(frame) || frame[index+1] != '[' {
			out.WriteByte(frame[index])
			index++
			continue
		}
		end := index + 2
		for end < len(frame) && (frame[end] < 0x40 || frame[end] > 0x7e) {
			end++
		}
		if end >= len(frame) {
			out.WriteString(frame[index:])
			break
		}
		if frame[end] != 'm' {
			out.WriteString(frame[index : end+1])
			index = end + 1
			continue
		}
		params := frame[index+2 : end]
		out.WriteString("\033[")
		if params == "" {
			out.WriteByte('0')
		} else {
			out.WriteString(params)
		}
		out.WriteByte(';')
		out.WriteString(background)
		out.WriteByte('m')
		index = end + 1
	}
	return out.String()
}

func drawStaticBackground(name string, width, height int, background string) {
	if width <= 0 || height <= 0 || name == "" || name == "none" {
		return
	}
	backgroundFrame := captureTerminalOutput(func() {
		drawStaticBackgroundRaw(name, width, height)
	})
	termPrint(applyANSIBackground(backgroundFrame, background))
}

func drawStaticBackgroundRaw(name string, width, height int) {
	switch name {
	case "soft-plasma":
		drawBackgroundSoftPlasma(width, height)
	case "aurora":
		drawBackgroundAurora(width, height)
	case "topography":
		drawBackgroundTopography(width, height)
	case "waves":
		drawBackgroundWaves(width, height)
	case "mesh":
		drawBackgroundMesh(width, height)
	case "constellation":
		drawBackgroundConstellation(width, height)
	case "ribbons":
		drawBackgroundRibbons(width, height)
	case "diagonal-flow":
		drawBackgroundDiagonalFlow(width, height)
	case "blueprint":
		drawBackgroundBlueprint(width, height)
	}
}

func staticBackgroundExportLines(name string, width, height int, defaultColor, background string) []exportLine {
	if name == "" || name == "none" {
		return nil
	}
	var buffer strings.Builder
	previous := terminalFrame
	terminalFrame = &buffer
	drawStaticBackground(name, width, height, background)
	terminalFrame = previous
	return ansiFrameToExportLines(buffer.String(), width, height, defaultColor)
}

func backgroundGlyph(value float64) rune {
	glyphs := []rune(" .·:░▒")
	index := int(math.Round(clampFloat(value, 0, 1) * float64(len(glyphs)-1)))
	return glyphs[index]
}

func backgroundColour(palette []string, value float64) string {
	index := int(math.Round(clampFloat(value, 0, 1) * float64(len(palette)-1)))
	return palette[index]
}

func drawBackgroundSoftPlasma(width, height int) {
	palette := []string{"\033[0;34m", "\033[0;36m", "\033[0;32m", "\033[0;35m"}
	for y := 0; y < height-1; y++ {
		for x := 0; x < width; x++ {
			v := (math.Sin(float64(x)/13.0) + math.Sin(float64(y)/5.0) + math.Sin(float64(x+y)/19.0) + 3.0) / 6.0
			glyph := backgroundGlyph(v * 0.78)
			if glyph == ' ' {
				continue
			}
			termPrintf("%s\033[%d;%dH%c", backgroundColour(palette, v), y+1, x+1, glyph)
		}
	}
}

func drawBackgroundAurora(width, height int) {
	palette := []string{"\033[0;32m", "\033[0;36m", "\033[0;35m", "\033[1;34m"}
	for band := 0; band < 4; band++ {
		for x := 0; x < width; x++ {
			center := float64(height)/2.0 + math.Sin(float64(x)/float64(7+band*3)+float64(band))*float64(2+band)
			thickness := 2.0 + float64(band)
			for dy := -2; dy <= 2; dy++ {
				y := int(math.Round(center + float64(dy)*thickness/2.0))
				if y < 0 || y >= height-1 {
					continue
				}
				glyph := []rune("·░▒▓")[min(3, abs(dy))]
				termPrintf("%s\033[%d;%dH%c", palette[band%len(palette)], y+1, x+1, glyph)
			}
		}
	}
}

func drawBackgroundTopography(width, height int) {
	for y := 0; y < height-1; y++ {
		for x := 0; x < width; x++ {
			v := math.Sin(float64(x)/8.0) + math.Sin(float64(y)/3.7) + math.Sin(float64(x+y)/11.0)
			if abs(int(math.Round(v*10)))%7 == 0 {
				termPrintf("\033[0;36m\033[%d;%dH·", y+1, x+1)
			}
		}
	}
}

func drawBackgroundWaves(width, height int) {
	for y := 1; y < height-1; y += 3 {
		color := "\033[0;34m"
		if y%2 == 0 {
			color = "\033[0;36m"
		}
		for x := 0; x < width; x++ {
			yy := y + int(math.Round(math.Sin(float64(x)/9.0+float64(y))*1.2))
			if yy >= 0 && yy < height-1 {
				glyph := '~'
				if x%9 == 0 {
					glyph = '·'
				}
				termPrintf("%s\033[%d;%dH%c", color, yy+1, x+1, glyph)
			}
		}
	}
}

func drawBackgroundMesh(width, height int) {
	points := deterministicPoints(width, max(1, height-1), max(10, width*height/180), 73)
	for i, a := range points {
		for j := i + 1; j < len(points); j++ {
			b := points[j]
			if abs(a.x-b.x)+abs(a.y-b.y) < max(8, width/8) {
				drawLine(a.x, a.y, b.x, b.y, "\033[0;34m", ".")
			}
		}
		termPrintf("\033[0;36m\033[%d;%dH·", a.y+1, a.x+1)
	}
}

func drawBackgroundConstellation(width, height int) {
	points := deterministicPoints(width, max(1, height-1), max(12, width*height/240), 109)
	for i, p := range points {
		if i%5 == 0 {
			termPrintf("\033[1;37m\033[%d;%dH·", p.y+1, p.x+1)
		} else {
			termPrintf("\033[0;36m\033[%d;%dH.", p.y+1, p.x+1)
		}
		if i > 0 && i%4 == 0 {
			prev := points[i-1]
			if abs(p.x-prev.x)+abs(p.y-prev.y) < max(10, width/6) {
				drawLine(prev.x, prev.y, p.x, p.y, "\033[0;34m", ".")
			}
		}
	}
}

func drawBackgroundRibbons(width, height int) {
	palette := []string{"\033[0;35m", "\033[0;34m", "\033[0;36m"}
	for ribbon := 0; ribbon < 5; ribbon++ {
		for x := 0; x < width; x++ {
			y := int(float64(height)/6.0*float64(ribbon+1) + math.Sin(float64(x)/float64(8+ribbon*2)+float64(ribbon))*3.0)
			if y >= 0 && y < height-1 {
				termPrintf("%s\033[%d;%dH%s", palette[ribbon%len(palette)], y+1, x+1, "▒")
			}
		}
	}
}

func drawBackgroundDiagonalFlow(width, height int) {
	palette := []string{"\033[0;34m", "\033[0;36m", "\033[0;35m"}
	glyphs := []rune("·░▒")
	for y := 0; y < height-1; y++ {
		for x := 0; x < width; x++ {
			if (x+y*2)%11 < 3 {
				value := (x + y) % len(palette)
				termPrintf("%s\033[%d;%dH%c", palette[value], y+1, x+1, glyphs[(x+y)%len(glyphs)])
			}
		}
	}
}

func drawBackgroundBlueprint(width, height int) {
	for y := 0; y < height-1; y++ {
		for x := 0; x < width; x++ {
			if y%6 == 0 || x%12 == 0 {
				termPrintf("\033[0;34m\033[%d;%dH·", y+1, x+1)
			}
		}
	}
	for x := 6; x < width; x += 24 {
		for y := 5; y < height-1; y += 12 {
			drawEllipse(x, y, 10, 4, "\033[0;36m", ".")
		}
	}
}

type exportCell struct {
	r     rune
	color string
}

func ansiFrameToExportLines(frame string, width, height int, defaultColor string) []exportLine {
	grid := make([][]exportCell, height)
	for row := range grid {
		grid[row] = make([]exportCell, width)
	}
	row, col := 0, 0
	color := defaultColor
	clear := func() {
		for y := range grid {
			for x := range grid[y] {
				grid[y][x] = exportCell{}
			}
		}
	}
	for i := 0; i < len(frame); {
		if frame[i] == 0x1b && i+1 < len(frame) && frame[i+1] == '[' {
			end := i + 2
			for end < len(frame) && !isANSICommandByte(frame[end]) {
				end++
			}
			if end >= len(frame) {
				break
			}
			params := frame[i+2 : end]
			switch frame[end] {
			case 'H', 'f':
				row, col = ansiCursorPosition(params)
				row = max(0, min(height-1, row))
				col = max(0, min(width-1, col))
			case 'J':
				if params == "2" || params == "" {
					clear()
					row, col = 0, 0
				}
			case 'm':
				if css := ansiParamsCSSColour(params); css != "" {
					color = css
				}
			}
			i = end + 1
			continue
		}
		r, size := utf8.DecodeRuneInString(frame[i:])
		if r == utf8.RuneError && size == 0 {
			break
		}
		switch r {
		case '\n':
			row++
			col = 0
		case '\r':
			col = 0
		default:
			if row >= 0 && row < height && col >= 0 && col < width && r != ' ' {
				grid[row][col] = exportCell{r: r, color: color}
			}
			col++
			if col >= width {
				col = 0
				row++
			}
		}
		i += size
	}
	var out []exportLine
	for y, cells := range grid {
		var parts []exportPart
		var run []rune
		runCol := 0
		runColor := ""
		flush := func() {
			if len(run) == 0 {
				return
			}
			parts = append(parts, exportPart{Col: runCol, Text: string(run), Color: runColor})
			run = nil
		}
		for x, cell := range cells {
			if cell.r == 0 {
				flush()
				continue
			}
			if len(run) == 0 {
				runCol = x
				runColor = cell.color
			} else if cell.color != runColor {
				flush()
				runCol = x
				runColor = cell.color
			}
			run = append(run, cell.r)
		}
		flush()
		if len(parts) > 0 {
			out = append(out, exportLine{Row: y, Role: "effect", Parts: parts})
		}
	}
	return out
}

func isANSICommandByte(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z')
}

func ansiCursorPosition(params string) (int, int) {
	if params == "" {
		return 0, 0
	}
	fields := strings.Split(params, ";")
	row, col := 1, 1
	if len(fields) >= 1 && fields[0] != "" {
		if parsed, err := strconv.Atoi(fields[0]); err == nil {
			row = parsed
		}
	}
	if len(fields) >= 2 && fields[1] != "" {
		if parsed, err := strconv.Atoi(fields[1]); err == nil {
			col = parsed
		}
	}
	return row - 1, col - 1
}

func exportLines(lines []Line, slide Slide, width, height, slideCount int) []exportLine {
	var out []exportLine
	seenTrueType := map[int]bool{}
	// A sampled object can produce many rows with identical metadata. Resolve
	// its foreground once per export pass, not once per raster row. Keep the
	// heading role in the key and the slide defaults local to this invocation.
	type colourKey struct {
		query   string
		heading bool
	}
	colours := make(map[colourKey]string)
	bodyColour, headingColour := ansiCSSColour(slideFG(slide)), ansiCSSColour(slideHeaderFG(slide))
	foreground := func(query string, heading bool) string {
		key := colourKey{query, heading}
		if colour, ok := colours[key]; ok {
			return colour
		}
		colour := bodyColour
		if heading {
			colour = headingColour
		}
		if fg := elementFG(query, heading); fg != "" {
			colour = ansiCSSColour(fg)
		}
		colours[key] = colour
		return colour
	}
	// Links depend on this deck's slide count; never share these results across
	// export passes. Cache unsuccessful lookups too for ordinary unlinked rows.
	links := make(map[string]string)
	linkFor := func(query string) string {
		if link, ok := links[query]; ok {
			return link
		}
		link := ""
		if target, ok := linkTargetFromQuery(query, slideCount); ok {
			link = target.Value
		}
		links[query] = link
		return link
	}
	backgrounds := make(map[string]string)
	codeBackground := func(query string) string {
		if colour, ok := backgrounds[query]; ok {
			return colour
		}
		colour := ansiCSSColour("100")
		if bg := elementBG(query); bg != "" {
			colour = ansiCSSColour(bg)
		}
		backgrounds[query] = colour
		return colour
	}
	transparencyIndex := indexExportTransparency(lines, width, height, slide)
	for index, line := range lines {
		if line.Role == "shape-label" && line.Element >= 0 && line.Element < len(slide.Elements) {
			if label, ok := shapeLabel(slide.Elements[line.Element]); ok {
				label.Query = line.Query
				q, _ := url.ParseQuery(line.Query)
				w, h := intQueryDefault(q, "width", 1), intQueryDefault(q, "height", 1)
				color := ansiCSSColour(elementFG(label.Query, false))
				out = append(out, exportLine{Row: line.Row, Col: line.Col, Element: line.Element, Role: "shape-label", Parts: []exportPart{{Col: line.Col, Text: line.Text, Color: color}}, TrueType: exportTrueTypeElement(label, w, h)})
			}
			continue
		}
		if line.Role == "truetype" {
			if seenTrueType[line.Element] || line.Element < 0 || line.Element >= len(slide.Elements) {
				continue
			}
			seenTrueType[line.Element] = true
			element := slide.Elements[line.Element]
			w, h := trueTypeBounds(element, width, height)
			color := foreground(element.Query, element.Kind == "heading")
			link := linkFor(element.Query)
			out = append(out, exportLine{Row: line.Row, Col: line.Col, Element: line.Element, Role: "truetype", Link: link, Parts: []exportPart{{Col: line.Col, Text: strings.Repeat(" ", w), Color: color}}, TrueType: exportTrueTypeElement(element, w, h)})
			continue
		}
		if line.Row < 0 || line.Row >= height || line.Col >= width || line.Text == "" {
			continue
		}
		transparentMask := transparencyMaskLine(line, slide)
		if transparentMask && line.Role == "shape" {
			continue
		}
		exportRole := line.Role
		if transparentMask {
			if line.Role == "image" {
				exportRole = "transparent-image"
			} else if line.Role != "code" {
				exportRole = "transparent-text"
			}
		}
		color := foreground(line.Query, line.Role == "heading")
		var parts []exportPart
		if line.Role == "code" {
			background := codeBackground(line.Query)
			parts = exportSolidTextParts(line.Text, line.Col, color, background, width)
			if transparentMask {
				for index := range parts {
					parts[index].Background = ""
				}
			}
		} else {
			parts = exportANSITextParts(line.Text, line.Col, color, width)
		}
		if len(parts) == 0 {
			continue
		}
		transparency := transparencyIndex.after(index, line.Row)
		parts = applyExportTransparencyToParts(parts, line.Row, transparency)
		if len(parts) == 0 {
			continue
		}
		link := ""
		if line.Role != "outline" {
			link = linkFor(line.Query)
		}
		out = append(out, exportLine{Row: line.Row, Col: line.Col, Element: line.Element, Role: exportRole, Link: link, Parts: parts})
	}
	return out
}

func transparentShapeExportLines(lines []Line, width, height int, slide Slide) []exportLine {
	cells := transparentShapeCells(lines, width, height, slide)
	if len(cells) == 0 {
		return nil
	}
	// Keep the rendered block glyph for transparent text and images.  A colour
	// cell alone describes a full rectangle and loses the quarter-block mask at
	// curved/antialiased edges (particularly visible on colour emoji).
	glyphs := map[int]map[int]rune{}
	for _, line := range lines {
		if !transparencyMaskLine(line, slide) || line.Role == "code" {
			continue
		}
		parts := exportANSITextParts(line.Text, line.Col, ansiCSSColour(slideFG(slide)), width)
		for _, part := range parts {
			for offset, r := range []rune(part.Text) {
				col := part.Col + offset
				if r == ' ' || col < 0 || col >= width || cells[line.Row] == nil || cells[line.Row][col] == "" {
					continue
				}
				if glyphs[line.Row] == nil {
					glyphs[line.Row] = map[int]rune{}
				}
				glyphs[line.Row][col] = r
			}
		}
	}
	rows := make([]int, 0, len(cells))
	for row := range cells {
		rows = append(rows, row)
	}
	sort.Ints(rows)
	out := make([]exportLine, 0, len(rows))
	for _, row := range rows {
		if row < 0 || row >= height || len(cells[row]) == 0 {
			continue
		}
		cols := make([]int, 0, len(cells[row]))
		for col := range cells[row] {
			cols = append(cols, col)
		}
		sort.Ints(cols)
		var parts []exportPart
		start := cols[0]
		prev := cols[0]
		bg := cells[row][start]
		flush := func(end int, runBG string) {
			var text strings.Builder
			for col := start; col <= end; col++ {
				if glyph := glyphs[row][col]; glyph != 0 {
					text.WriteRune(glyph)
				} else {
					text.WriteByte(' ')
				}
			}
			parts = append(parts, exportPart{
				Col:        start,
				Text:       text.String(),
				Color:      ansiCSSColour(slideFG(slide)),
				Background: ansiCSSColour(runBG),
			})
		}
		for _, col := range cols[1:] {
			if col == prev+1 && cells[row][col] == bg {
				prev = col
				continue
			}
			flush(prev, bg)
			start = col
			prev = col
			bg = cells[row][col]
		}
		flush(prev, bg)
		if len(parts) > 0 {
			out = append(out, exportLine{Row: row, Role: "transparent", Parts: parts})
		}
	}
	return out
}

func applyExportTransparencyToParts(parts []exportPart, row int, transparency map[int]map[int]string) []exportPart {
	rowCells := transparency[row]
	if len(rowCells) == 0 {
		return parts
	}
	var out []exportPart
	appendPart := func(col int, text, color, background string) {
		if text == "" {
			return
		}
		if len(out) > 0 {
			last := &out[len(out)-1]
			if last.Col+displayWidth(last.Text) == col && last.Color == color && last.Background == background {
				last.Text += text
				return
			}
		}
		out = append(out, exportPart{Col: col, Text: text, Color: color, Background: background})
	}
	for _, part := range parts {
		color := part.Color
		if color == "" {
			color = "#f3efe0"
		}
		for offset, r := range []rune(part.Text) {
			col := part.Col + offset
			bg := part.Background
			cellBG := rowCells[col]
			cellColor := color
			if cellBG != "" {
				bg = ansiCSSColour(cellBG)
				cellColor = blendCSSForTransparency(color, bg)
			}
			appendPart(col, string(r), cellColor, bg)
		}
	}
	return out
}

func blendCSSForTransparency(css, overlay string) string {
	return ansiCSSColour(blendFGForTransparency(cssColourToFG(css, "37"), cssColourToFG(overlay, "30")))
}

func exportSolidTextParts(text string, baseCol int, color, background string, width int) []exportPart {
	if baseCol >= width {
		return nil
	}
	if baseCol < 0 {
		text = runeSliceWithPadding(text, -baseCol, displayWidth(text))
		baseCol = 0
	}
	text = crop(text, max(0, width-baseCol))
	if text == "" {
		return nil
	}
	return []exportPart{{Col: baseCol, Text: text, Color: color, Background: background}}
}

func exportANSITextParts(text string, baseCol int, defaultColor string, width int) []exportPart {
	var parts []exportPart
	normalColor := defaultColor
	color := defaultColor
	background := ""
	bold := false
	col := baseCol
	var run []rune
	runCol := col
	flush := func() {
		if len(run) == 0 {
			return
		}
		parts = append(parts, exportPart{Col: runCol, Text: string(run), Color: color, Background: background})
		run = nil
	}
	for i := 0; i < len(text) && col < width; {
		if text[i] == 0x1b {
			flush()
			end := i + 1
			for end < len(text) && text[end] != 'm' {
				end++
			}
			if end < len(text) {
				sequence := text[i : end+1]
				if ansiParamsContain(sequence, "0") || ansiParamsContain(sequence, "39") {
					normalColor = defaultColor
					color = defaultColor
				}
				if ansiParamsContain(sequence, "0") || ansiParamsContain(sequence, "49") {
					background = ""
				}
				if ansiSequenceBoldOff(sequence) {
					bold = false
					color = normalColor
				}
				if ansiSequenceBoldOn(sequence) {
					bold = true
					color = lightenCSSColour(normalColor)
				}
				if css := ansiSequenceCSSColour(sequence); css != "" {
					normalColor = css
					color = css
					if bold {
						color = lightenCSSColour(normalColor)
					}
				}
				if css := ansiSequenceCSSBackground(sequence); css != "" {
					background = css
				}
				i = end + 1
				continue
			}
		}
		r, size := utf8.DecodeRuneInString(text[i:])
		if r == utf8.RuneError && size == 0 {
			break
		}
		if r == ' ' && background == "" {
			flush()
			col++
			i += size
			continue
		}
		if len(run) == 0 {
			runCol = col
		}
		run = append(run, r)
		col++
		i += size
	}
	flush()
	return parts
}

func ansiSequenceCSSBackground(sequence string) string {
	if background := ansiSequenceBG(sequence); background != "" {
		return ansiCSSColour(background)
	}
	return ""
}

func ansiSequenceBoldOn(sequence string) bool {
	return ansiParamsContain(sequence, "1")
}

func ansiSequenceBoldOff(sequence string) bool {
	return ansiParamsContain(sequence, "0") || ansiParamsContain(sequence, "22")
}

func ansiParamsContain(sequence, needle string) bool {
	sequence = strings.TrimPrefix(sequence, "\033[")
	sequence = strings.TrimSuffix(sequence, "m")
	for _, field := range strings.Split(sequence, ";") {
		if field == needle {
			return true
		}
	}
	return false
}

func ansiSequenceCSSColour(sequence string) string {
	sequence = strings.TrimPrefix(sequence, "\033[")
	sequence = strings.TrimSuffix(sequence, "m")
	return ansiParamsCSSColour(sequence)
}

func ansiParamsCSSColour(params string) string {
	fields := strings.Split(params, ";")
	for i := 0; i < len(fields); i++ {
		if fields[i] == "0" {
			continue
		}
		if (fields[i] == "38" || fields[i] == "48") && i+4 < len(fields) && fields[i+1] == "2" {
			return fmt.Sprintf("rgb(%s,%s,%s)", fields[i+2], fields[i+3], fields[i+4])
		}
		if parsed, err := strconv.Atoi(fields[i]); err == nil && parsed >= 30 && parsed <= 37 {
			return ansiCSSColour(strconv.Itoa(parsed))
		}
		if parsed, err := strconv.Atoi(fields[i]); err == nil && parsed >= 90 && parsed <= 97 {
			return ansiCSSColour(strconv.Itoa(parsed))
		}
	}
	return ""
}

func ansiCSSColour(code string) string {
	parts := strings.Split(code, ";")
	if len(parts) == 5 && (parts[0] == "38" || parts[0] == "48") && parts[1] == "2" {
		return fmt.Sprintf("rgb(%s,%s,%s)", parts[2], parts[3], parts[4])
	}
	if parsed, err := strconv.Atoi(code); err == nil {
		colours := map[int]string{
			30: "#000000", 31: "#aa0000", 32: "#00aa00", 33: "#aaaa00",
			34: "#0000aa", 35: "#aa00aa", 36: "#00aaaa", 37: "#f3efe0",
			40: "#000000", 41: "#aa0000", 42: "#00aa00", 43: "#aaaa00",
			44: "#0000aa", 45: "#aa00aa", 46: "#00aaaa", 47: "#f3efe0",
			90: "#555555", 91: "#ff5555", 92: "#55ff55", 93: "#ffff55",
			94: "#5555ff", 95: "#ff55ff", 96: "#55ffff", 97: "#ffffff",
			100: "#555555", 101: "#ff5555", 102: "#55ff55", 103: "#ffff55",
			104: "#5555ff", 105: "#ff55ff", 106: "#55ffff", 107: "#ffffff",
		}
		if css, ok := colours[parsed]; ok {
			return css
		}
	}
	return "#f3efe0"
}

func readPreservedExportHead(path string) preservedExportHead {
	data, err := os.ReadFile(path)
	if err != nil {
		return preservedExportHead{}
	}
	return preservedExportHeadFromHTML(string(data))
}

func preservedExportHeadFromHTML(existing string) preservedExportHead {
	head, ok := extractHTMLHead(existing)
	if !ok {
		return preservedExportHead{}
	}
	return preservedExportHead{
		Title:   firstHTMLTagBlock(head, "title"),
		Metas:   customHeadMetaTags(head),
		Scripts: customHeadScriptTags(head),
	}
}

func extractHTMLHead(html string) (string, bool) {
	lower := strings.ToLower(html)
	start := strings.Index(lower, "<head")
	if start < 0 {
		return "", false
	}
	startClose := strings.Index(html[start:], ">")
	if startClose < 0 {
		return "", false
	}
	contentStart := start + startClose + 1
	end := strings.Index(lower[contentStart:], "</head>")
	if end < 0 {
		return "", false
	}
	return html[contentStart : contentStart+end], true
}

func firstHTMLTagBlock(html, tag string) string {
	re := regexp.MustCompile(`(?is)<` + regexp.QuoteMeta(tag) + `\b[^>]*>.*?</` + regexp.QuoteMeta(tag) + `\s*>`)
	return strings.TrimSpace(re.FindString(html))
}

func customHeadMetaTags(head string) []string {
	re := regexp.MustCompile(`(?is)<meta\b[^>]*>`)
	var metas []string
	for _, tag := range re.FindAllString(head, -1) {
		if isGeneratedHeadMeta(tag) {
			continue
		}
		metas = append(metas, strings.TrimSpace(tag))
	}
	return metas
}

func isGeneratedHeadMeta(tag string) bool {
	lower := strings.ToLower(tag)
	return strings.Contains(lower, "charset=") || htmlAttrEquals(lower, "name", "viewport") || htmlAttrEquals(lower, "name", "generator")
}

func htmlAttrEquals(tag, attr, value string) bool {
	quotedValue := regexp.QuoteMeta(value)
	re := regexp.MustCompile(`\b` + regexp.QuoteMeta(attr) + `\s*=\s*(?:"` + quotedValue + `"|'` + quotedValue + `'|` + quotedValue + `(?:[\s/>]|$))`)
	return re.MatchString(tag)
}

func customHeadScriptTags(head string) []string {
	re := regexp.MustCompile(`(?is)<script\b[^>]*>.*?</script\s*>`)
	var scripts []string
	for _, tag := range re.FindAllString(head, -1) {
		lower := strings.ToLower(tag)
		if htmlAttrEquals(lower, "id", "keynope-data") {
			continue
		}
		scripts = append(scripts, strings.TrimSpace(tag))
	}
	return scripts
}

