type liveSlideRenderer struct {
	effect    string
	width     int
	height    int
	matrix    *matrixEffect
	stars     *starsEffect
	fireworks *burstEffect
}

func (renderer *liveSlideRenderer) draw(slide Slide, width, height, page, frame int, overlay func([]Line)) {
	geometry := fittedTerminalContentGeometry(width, height)
	if renderer.effect != slide.Effect || renderer.width != geometry.Width || renderer.height != geometry.Height || renderer.matrix == nil {
		renderer.effect = slide.Effect
		renderer.width = geometry.Width
		renderer.height = geometry.Height
		renderer.matrix = newMatrix(geometry.Width, geometry.Height)
		renderer.stars = newStars(geometry.Width, geometry.Height)
		renderer.fireworks = newBursts(slide.Effect, geometry.Width, geometry.Height)
	}
	flushTerminalFrame(func() {
		clearPhysicalTerminalViewport()
		drawTerminalSlideCanvas(slide, width, height, func(canvas terminalContentGeometry) {
			if slide.Effect != "" {
				drawEffectFrame(slide.Effect, canvas.Width, canvas.Height, frame, renderer.matrix, renderer.stars, renderer.fireworks, slideBG(slide))
			}
		})
		lines := displayLines(slide, width, height, page)
		drawOverlayLines(lines, width, height, slide)
		drawLinkUnderlines(lines, width, height, slide)
		if overlay != nil {
			overlay(lines)
		}
		termPrint("\033[0m")
	})
}

type pickerColour struct {
	Hex     string
	FG, BG  string
	R, G, B int
}

func currentElementHexForElement(element Element) string {
	values, err := url.ParseQuery(element.Query)
	if err != nil {
		return ""
	}
	value := values.Get("fg")
	if element.Kind == "heading" {
		value = values.Get("header")
		if value == "" {
			value = values.Get("fg")
		}
	}
	if hex, ok := normalizeHexColour(value); ok {
		return hex
	}
	if code, ok := ansiFG(value); ok {
		return ansiCodeName(code, false)
	}
	return ""
}

func cloneSlide(slide Slide) Slide {
	copySlide := slide
	if slide.ThemeColors != nil {
		colors := *slide.ThemeColors
		copySlide.ThemeColors = &colors
	}
	copySlide.Elements = append([]Element(nil), slide.Elements...)
	for index := range copySlide.Elements {
		copySlide.Elements[index].Extra = cloneJSONExtensions(slide.Elements[index].Extra)
	}
	copySlide.Extra = cloneJSONExtensions(slide.Extra)
	copySlide.Engagement = cloneEngagement(slide.Engagement)
	copySlide.EngagementResult = cloneEngagementResult(slide.EngagementResult)
	return copySlide
}

func cloneSlides(slides []Slide) []Slide {
	out := make([]Slide, len(slides))
	for i, slide := range slides {
		out[i] = cloneSlide(slide)
	}
	return out
}

const editHistoryLimit = 100

func insertElementAfter(slide *Slide, selected int, element Element) int {
	insertAt := selected + 1
	if selected < 0 || selected >= len(slide.Elements) {
		slide.Elements = append(slide.Elements, element)
		return len(slide.Elements) - 1
	}
	slide.Elements = append(slide.Elements, Element{})
	copy(slide.Elements[insertAt+1:], slide.Elements[insertAt:])
	slide.Elements[insertAt] = element
	return insertAt
}

func newShapeElement(shape string) Element {
	if shape == "" {
		shape = "circle"
	}
	query := ""
	query = setQueryValue(query, "shape", shape)
	switch shape {
	case "square":
		query = setShapeSize(query, 8, 4)
	case "triangle":
		query = setShapeSize(query, 12, 6)
	case "diamond":
		query = setShapeSize(query, 11, 6)
	default:
		query = setShapeSize(query, 10, 6)
	}
	return Element{Kind: "shape", ID: newStableID("shape"), Query: query}
}

